package com.classvoice.controller; import com.classvoice.dao.LectureDAO; import com.classvoice.model.User; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/student/dashboard") public class ActiveLectureServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{r.setAttribute("activeLectures",new LectureDAO().findActive());r.getRequestDispatcher("/WEB-INF/views/student-dashboard.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}}
